examples.template:
let query = MonarchSlashMenuQuery.find(in: text)
VStack(spacing: 0) {
    MonarchSlashMenu(query, items: commands, groupOrder: [{{groups.0}}, {{groups.1}}, {{groups.2}}], visibleRows: 10) { item in
        if let query { text = query.replacing(in: text, with: markdown[item.id] ?? "") }
    }
    .padding(.bottom, theme.spacing.space2)
    VStack(alignment: .leading, spacing: theme.spacing.space1) {
        Text({{field.label}}).monarchTextStyle(.label)
        TextField({{field.label}}, text: $text, prompt: Text({{field.placeholder}}), axis: .vertical)
            .padding(theme.spacing.space2)
            .overlay(RoundedRectangle(cornerRadius: theme.radius.md).stroke(theme.colors.borderInput))
    }
}

